import java.util.*;

class Solution {
    public int findNumbers(int[] nums) {
        int count = 0;
        for (int x : nums) {
            int digits = 0;
            while (x > 0) {      // strip one digit at a time
                x /= 10;
                digits++;
            }
            if (digits % 2 == 0) count++;
        }
        return count;
    }
}

